def run_length(s: str) -> str:
    """Run-length encode: each maximal run of a character c of length k becomes c followed by k. 'aaab' -> 'a3b1'."""
    if not s:
        return ""

    result = ""
    count = 1
    for i in range(len(s)):
        if i + 1 < len(s) and s[i] == s[i + 1]:
            count += 1
        else:
            result += s[i] + str(count)
            count = 1
    return result

