def merge_intervals(xs: list[tuple[int, int]]) -> list[tuple[int, int]]:
    """Merge overlapping closed intervals; return them sorted by start. Touching intervals (1,2),(2,3) merge."""
    if not xs:
        return []

    xs.sort()
    merged = []
    current_interval = xs[0]

    for interval in xs[1:]:
        if interval[0] <= current_interval[1]:
            current_interval = (current_interval[0], max(current_interval[1], interval[1]))
        else:
            merged.append(current_interval)
            current_interval = interval

    merged.append(current_interval)
    return merged

